package net.nuggetmc.tplus.compat.bukkit.event.player;
import net.nuggetmc.tplus.compat.bukkit.event.*; import net.nuggetmc.tplus.compat.bukkit.event.block.Action; import net.nuggetmc.tplus.compat.bukkit.entity.Player; import net.nuggetmc.tplus.compat.bukkit.block.Block; import net.nuggetmc.tplus.compat.bukkit.block.BlockFace; import net.nuggetmc.tplus.compat.bukkit.inventory.*;
public class PlayerInteractEvent extends Event implements Cancellable { private final Player player;private final Action action;private final ItemStack item;private final Block block;private final BlockFace face;private final EquipmentSlot hand;private boolean cancelled;private Result useBlock=Result.DEFAULT,useItem=Result.DEFAULT; public PlayerInteractEvent(Player p,Action a,ItemStack i,Block b,BlockFace f,EquipmentSlot h){player=p;action=a;item=i;block=b;face=f;hand=h;}public Player getPlayer(){return player;}public Action getAction(){return action;}public ItemStack getItem(){return item;}public Block getClickedBlock(){return block;}public BlockFace getBlockFace(){return face;}public EquipmentSlot getHand(){return hand;}public Result useInteractedBlock(){return useBlock;}public void setUseInteractedBlock(Result r){useBlock=r;}public Result useItemInHand(){return useItem;}public void setUseItemInHand(Result r){useItem=r;}public boolean isCancelled(){return cancelled;}public void setCancelled(boolean v){cancelled=v;} }
